import random
from taskdag.scheduler import Scheduler

def transitive_dep_closure(s, name):
    """Ancestors of name: tasks name depends on, directly or transitively
    (following _deps edges). Independent spec oracle, NOT the impl's rule."""
    seen, stack = set(), list(s._deps[name])
    while stack:
        d = stack.pop()
        if d in seen or d not in s._deps:
            continue
        seen.add(d)
        stack.extend(s._deps[d])
    return seen

def oracle(s, failing):
    """Independent reference for run(): a task is skipped iff it has a failing
    task among its ancestors; otherwise it runs (fails iff in `failing`)."""
    status = {}
    for name in s.tasks():
        if transitive_dep_closure(s, name) & failing:
            status[name] = "skipped"
        elif name in failing:
            status[name] = "failed"
        else:
            status[name] = "ok"
    return status

rng = random.Random(20240903)
for trial in range(1500):
    n = rng.randint(0, 25)
    s = Scheduler()
    names = ["t%02d" % i for i in range(n)]
    for nm in names:
        s.add_task(nm)
    # random edges from higher index -> lower index keeps graph acyclic
    for i in range(n):
        for j in range(i):
            if rng.random() < 0.25:
                s.add_dependency(names[i], names[j])

    failing = {nm for nm in names if rng.random() < 0.35}
    expect = oracle(s, failing)
    calls = []
    def runner(name):
        calls.append(name)
        if name in failing:
            raise RuntimeError("boom %s" % name)
    status = s.run(runner)
    assert set(status) == set(names), (trial, status, names)
    assert status == expect, (
        "MISMATCH trial %d\nimpl %s\noracle %s\ngraph %r\nfailing %s"
        % (trial, status, expect, {k: sorted(v) for k, v in s._deps.items()}, failing)
    )
    # every skipped task's runner was never called; called set == runnable set
    assert set(calls) == set(status) - {k for k, v in status.items() if v == "skipped"}, trial
    # call order is a topological order restricted to called tasks
    called = set(calls)
    for i, nm in enumerate(calls):
        assert not (s._deps[nm] & called - set(calls[:i])), (trial, nm, calls)
    # exactly-once + repeatability
    assert len(calls) == len(set(calls)), trial
    calls2 = []
    def runner2(name):
        calls2.append(name)
        if name in failing:
            raise RuntimeError("boom %s" % name)
    assert s.run(runner2) == status and calls2 == calls, trial
print("1500 randomized differential trials PASSED")
